package test
import("bytes";"context";"crypto/rand";"crypto/rsa";"crypto/x509";"crypto/x509/pkix";"encoding/pem";"math/big";"os";"testing";"time";ncrypto "github.com/TamilSelvam22112003/Nls-NetOS-v0.1.2/prototype/NetOS-v0.1.0/internal/crypto";"github.com/TamilSelvam22112003/Nls-NetOS-v0.1.2/prototype/NetOS-v0.1.0/internal/boot";"github.com/TamilSelvam22112003/Nls-NetOS-v0.1.2/prototype/NetOS-v0.1.0/internal/protocol")
func TestHappyPathChallengeAndCodec(t *testing.T){k,_:=rsa.GenerateKey(rand.Reader,2048);s:=ncrypto.Signer{PrivateKey:k,Serial:"S",Chassis:"C",BoardCertificate:"CERT"};n:=make([]byte,32);rand.Read(n);r,e:=s.SignChallenge(n);if e!=nil||len(r.Signature)==0{t.Fatalf("challenge signing failed: %v",e)};b,e:=(protocol.Codec{}).Encode(protocol.Message{Type:protocol.MessageResponse,Fields:map[protocol.TLVType][]byte{protocol.FieldSignature:r.Signature}});if e!=nil{t.Fatal(e)};m,e:=(protocol.Codec{}).Decode(bytes.NewReader(b));if e!=nil||m.Type!=protocol.MessageResponse{t.Fatalf("codec round trip failed: %v",e)}}
func TestOrgMismatch(t *testing.T){root,server:=fixtureCA(t,"Right Org");defer os.Remove(root);if e:=ncrypto.VerifyServer([]*x509.Certificate{server},root,"Wrong Org");e==nil{t.Fatal("expected organization mismatch")}}
func TestExpiredSerial(t *testing.T){k,_:=rsa.GenerateKey(rand.Reader,2048);now:=time.Now();t1:=&x509.Certificate{SerialNumber:big.NewInt(1),Subject:pkix.Name{Organization:[]string{"Org"}},NotBefore:now.Add(-2*time.Hour),NotAfter:now.Add(-time.Hour)};d,_:=x509.CreateCertificate(rand.Reader,t1,t1,&k.PublicKey,k);c,_:=x509.ParseCertificate(d);if time.Now().Before(c.NotAfter){t.Fatal("fixture is not expired")}}
func TestInvalidSignatureTriggersRetry(t *testing.T){ctx,cancel:=context.WithTimeout(context.Background(),25*time.Millisecond);defer cancel();p:=boot.RetryPolicy{Initial:time.Millisecond,Max:2*time.Millisecond};calls:=0;e:=p.Retry(ctx,[]string{"127.0.0.1:12346"},func(context.Context,string)error{calls++;return os.ErrPermission});if e==nil||calls<2{t.Fatalf("retry not triggered: err=%v calls=%d",e,calls)}}
func fixtureCA(t *testing.T,org string)(string,*x509.Certificate){t.Helper();k,_:=rsa.GenerateKey(rand.Reader,2048);r:=&x509.Certificate{SerialNumber:big.NewInt(2),Subject:pkix.Name{Organization:[]string{org}},NotBefore:time.Now().Add(-time.Minute),NotAfter:time.Now().Add(time.Hour),IsCA:true,BasicConstraintsValid:true,KeyUsage:x509.KeyUsageCertSign};d,_:=x509.CreateCertificate(rand.Reader,r,r,&k.PublicKey,k);c,_:=x509.ParseCertificate(d);f,_:=os.CreateTemp(t.TempDir(),"root.pem");pem.Encode(f,&pem.Block{Type:"CERTIFICATE",Bytes:d});f.Close();return f.Name(),c}
